export const timelineIntervalPageLimit=64;
export function timelineRowPage(row,selection,states,limit=timelineIntervalPageLimit){
 const previous=states.get(row.id),follow=previous?.selection!==selection&&typeof selection==='string'&&selection!==row.id&&row.contains?.(selection),page=row.intervalPage({offset:previous?.offset||0,limit,...follow?{selection}:{}});let result=page;
 if(page.total&&page.offset>=page.total)result=row.intervalPage({offset:Math.floor((page.total-1)/limit)*limit,limit});states.set(row.id,{offset:result.offset,selection});return result;
}
export function timelineItemsPageMarkup(row,page,escape){if(page.total<=page.limit)return '';const button=(offset,label,disabled)=>'<button data-timeline-items-row="'+escape(row.id)+'" data-timeline-items-offset="'+offset+'" aria-label="'+label+'"'+(disabled?' disabled':'')+'>'+(label==='이전 구간'?'‹':'›')+'</button>';return '<span class="timeline-item-pages" role="group" aria-label="겹친 구간 페이지">'+button(page.previousOffset??0,'이전 구간',page.previousOffset===null)+'<output aria-live="polite">'+(page.offset+1)+'–'+(page.offset+page.items.length)+' / '+page.total+'</output>'+button(page.nextOffset??page.offset,'다음 구간',page.nextOffset===null)+'</span>';}
export function changeTimelineItemsPage(editor,row,offset){if(typeof row!=='string'||!Number.isInteger(offset)||offset<0||!editor.sequenceRows?.some(r=>r.id===row&&typeof r.intervalPage==='function'))throw Error('타임라인 구간 페이지를 확인하세요.');editor.timelineItemPages??=new Map();editor.timelineItemPages.set(row,{offset,selection:editor.selection});editor.sequenceWindow=null;editor.refreshSequenceRows();const buttons=editor.element?.querySelectorAll?.('[data-timeline-items-row]')||[];[...buttons].find(b=>b.dataset.timelineItemsRow===row&&!b.disabled)?.focus({preventScroll:true});}
export function readTimelineRowItems(rows,{row,range,offset=0,limit=64,selection}={}){if(typeof row!=='string'||!row||row.length>240)throw Error('타임라인 행 ID를 확인하세요.');const found=rows.find(r=>r.id===row);if(!found)throw Error('타임라인 행을 찾을 수 없어요.');const page=found.intervalPage({offset,limit,range,selection});return{row,type:found.type,...page,items:structuredClone(page.items),intervalsOnly:true,readOnly:true};}
export const timelineIntervalPagesContract={documents:['sequenceasset','montage'],read:'timeline.row.items.read',limit:'1..256, default64; exact visible total and next/previous offsets, deterministic start then original authored order; interval items only, keys retain existing curve APIs',index:'Existing per-render interval index plus lazy minimum-end subtree counts; dense fully matching subtrees skip as a whole, bounded page emission, optional lazy unique-ID selection rank. Full query retains authored order and every original item.',editor:'Rows with >64 visible intervals show explicit previous/count/next controls; every interval remains addressable, selected external navigation follows its page. Keys retain the existing overview. Page state is view-only, no authored/revision/dirty/Undo/playhead change.',lifetime:'Row-owned indexes dropped on existing document rerender/edit; no global cache or authored-item copies for hidden pages. New minimum/id structures only on paged reads; legacy query memory behavior unchanged.',limits:'Overlap is paged explicitly, not drawn all at once. Initial row/index build and irregular ranges can still visit many intervals; not constant-time worst case or runtime/FPS/GUI/device proof. Existing fixed row-height virtualization remains.'};
